function FontLoader({ children }) {
  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,400..600;1,9..144,400..600&family=Inter:wght@400;500;600;700&family=Fredoka:wght@600;700&family=Alex+Brush&family=Allura&family=Parisienne&family=Playfair+Display:ital,wght@0,700;0,900;1,700;1,900&family=Cormorant+Garamond:ital,wght@0,600;1,600&family=Bodoni+Moda:ital,wght@0,600;1,600&family=EB+Garamond:ital,wght@0,600;1,600&display=swap');
        * { font-family: 'Inter', sans-serif; }
        .hide-scrollbar::-webkit-scrollbar { display: none; }
        .hide-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        /* Respects the OS-level "reduce motion" setting — vestibular
           disorders can make scale/transition effects genuinely
           uncomfortable, not just a preference. Cuts every transition and
           animation down to near-instant rather than removing feedback
           entirely, so state changes are still visible, just not animated. */
        @media (prefers-reduced-motion: reduce) {
          *, *::before, *::after {
            animation-duration: 0.01ms !important;
            animation-iteration-count: 1 !important;
            transition-duration: 0.01ms !important;
          }
        }
      `}</style>
      {children}
    </>
  );
}

