const hasArtifactStorage = typeof window !== "undefined" && !!window.storage;
const hasLocalStorage = (() => {
  if (typeof window === "undefined" || !window.localStorage) return false;
  try {
    const t = "__bonce_probe__";
    window.localStorage.setItem(t, "1");
    window.localStorage.removeItem(t);
    return true;
  } catch (e) {
    return false; // e.g. private-browsing storage restrictions
  }
})();
const memoryStore = {};

async function storeGet(key) {
  if (hasArtifactStorage) {
    try {
      const r = await window.storage.get(key, false);
      return r ? r.value : null;
    } catch (e) {
      return null;
    }
  }
  if (hasLocalStorage) {
    try {
      return window.localStorage.getItem(key);
    } catch (e) {
      return null;
    }
  }
  return memoryStore[key] ?? null;
}
async function storeSet(key, value) {
  if (hasArtifactStorage) {
    try {
      await window.storage.set(key, value, false);
      return;
    } catch (e) {
      /* fall through */
    }
  }
  if (hasLocalStorage) {
    try {
      window.localStorage.setItem(key, value);
      return;
    } catch (e) {
      /* fall through */
    }
  }
  memoryStore[key] = value;
}

function uid() {
  return Math.random().toString(36).slice(2, 10) + Date.now().toString(36).slice(-4);
}
function hashId(str) {
  let h = 0;
  for (let i = 0; i < String(str).length; i++) h = (h * 31 + String(str).charCodeAt(i)) & 0x7fffffff;
  return h;
}

// hashId's rolling string hash is fine for its original job (stable skin
// index for one fixed string) but its low bits are dominated by whatever
// character comes last — concatenating a seed onto an id and hashing the
// result barely moved the output across totally different seeds, which
// would have made Shuffle silently do nothing. This is a proper integer
// bit-mixer (a standard splitmix-style finalizer) for combining two
// numbers into a well-distributed result instead.
function mix32(a, b) {
  let x = (a ^ b) >>> 0;
  x = Math.imul(x ^ (x >>> 16), 0x45d9f3b) >>> 0;
  x = Math.imul(x ^ (x >>> 16), 0x45d9f3b) >>> 0;
  x = (x ^ (x >>> 16)) >>> 0;
  return x;
}
const BONCE_MARK_SM = "data:image/png;base64,";
const BONCE_MARK_LG = "data:image/png;base64,";

const DAY = 86400000;

/* ---------------------------------------------------------------------- */
/* Recurrence — three genuinely different kinds, not variations of one.    */
/* Weekly stays interval-based (every N weeks, anchored to a weekday) since */
/* that's naturally drift-free — N weeks is always a whole number of days. */
/* Monthly and annual are calendar-anchored (the 1st, 15 March) rather than */
/* "N days after you last did it", which is the actual fix for the annual */
/* case — MOT doesn't move just because you dealt with it three days late. */
/* ---------------------------------------------------------------------- */

const WEEKDAY_NAMES = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const WEEKDAY_SHORT = ["S", "M", "T", "W", "T", "F", "S"];
const MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

function ordinal(n) {
  const v = n % 100;
  if (v >= 11 && v <= 13) return `${n}th`;
  switch (n % 10) {
    case 1: return `${n}st`;
    case 2: return `${n}nd`;
    case 3: return `${n}rd`;
    default: return `${n}th`;
  }
}

// Clamps the day to whatever the target month actually has — 31 in a
// 30-day month, or Feb 29/30/31, lands on that month's real last day
// instead of overflowing into the next one.
function safeDate(year, month0, day) {
  const daysInMonth = new Date(year, month0 + 1, 0).getDate();
  return new Date(year, month0, Math.min(day, daysInMonth), 9, 0, 0).getTime();
}

// The next time a recurrence rule falls due, at or after `fromTs`.
function nextOccurrence(r, fromTs) {
  if (!r) return null;
  const from = new Date(fromTs);
  if (r.freq === "annual") {
    let next = safeDate(from.getFullYear(), r.month - 1, r.day);
    if (next <= fromTs) next = safeDate(from.getFullYear() + 1, r.month - 1, r.day);
    return next;
  }
  if (r.freq === "monthly") {
    let next = safeDate(from.getFullYear(), from.getMonth(), r.day);
    if (next <= fromTs) {
      const m = from.getMonth() + 1;
      next = safeDate(from.getFullYear() + (m > 11 ? 1 : 0), m % 12, r.day);
    }
    return next;
  }
  if (r.freq === "weekly") {
    // Two genuinely different behaviors live under "weekly", not one —
    // fixed keeps the original schedule no matter how late you are
    // (medication: 3 days late doesn't mean the whole future schedule
    // shifts), flexible restarts the count from whenever you actually
    // did it (hoovering the stairs: being late just means it's due a
    // bit later too, which is fine for that kind of thing).
    if (r.flexible) return fromTs + Math.max(1, r.weeks) * 7 * DAY;
    const anchor = r.anchor || fromTs;
    const weekMs = Math.max(1, r.weeks) * 7 * DAY;
    if (fromTs <= anchor) return anchor;
    const cycles = Math.ceil((fromTs - anchor) / weekMs);
    return anchor + cycles * weekMs;
  }
  return null;
}

// Plain-English version for badges and confirmation text.
function describeRecurrence(r) {
  if (!r) return null;
  if (r.freq === "annual") return `every ${ordinal(r.day)} ${MONTH_NAMES[r.month - 1]}`;
  if (r.freq === "monthly") return `monthly on the ${ordinal(r.day)}`;
  if (r.freq === "weekly") {
    if (r.flexible) return `every ${r.weeks} week${r.weeks === 1 ? "" : "s"} from whenever you do it`;
    return `every ${r.weeks} week${r.weeks === 1 ? "" : "s"} on ${WEEKDAY_NAMES[r.weekday]}`;
  }
  return null;
}

// Short version for the small badge on a card/row.
function describeRecurrenceShort(r) {
  if (!r) return null;
  if (r.freq === "annual") return `${r.day} ${MONTH_NAMES[r.month - 1].slice(0, 3)}`;
  if (r.freq === "monthly") return `${ordinal(r.day)}`;
  if (r.freq === "weekly") return r.flexible ? `~${r.weeks}w` : `${r.weeks}w`;
  return null;
}

// The starting anchor for a brand-new weekly recurrence — the next
// occurrence of that weekday from now, so the first cycle lands on the
// right day instead of "N weeks from whenever you happened to set it up".
function firstWeeklyAnchor(weekday, fromTs = Date.now()) {
  const from = new Date(fromTs);
  const diff = (weekday - from.getDay() + 7) % 7;
  return safeDate(from.getFullYear(), from.getMonth(), from.getDate() + diff);
}


const daysAgo = (n) => Date.now() - n * DAY;

function inferType(text) {
  const t = text.toLowerCase();
  if (/\b(buy|get|pick up|order|purchase|grab)\b/.test(t)) return "buy";
  if (/\b(project|launch|build|redesign|plan)\b/.test(t)) return "project";
  if (/\b(remember|idea|note|think about|look into|research)\b/.test(t)) return "note";
  return "task";
}
function inferMinutes(text) {
  return /\b(quick|call|email|text|reply|bin|water)\b/i.test(text) ? 5 : null;
}

const STOP_WORDS = new Set([
  "the", "a", "an", "my", "your", "our", "some", "of", "to", "for", "with", "and", "or",
  "in", "on", "at", "out", "up", "off", "from", "about", "into", "over", "back", "that",
  "this", "it", "its", "then", "also",
]);
const wordsOf = (t) => String(t || "").trim().split(/\s+/).filter(Boolean);
const normalise = (w) => w.toLowerCase().replace(/[^a-z']/g, "");

function looksLikeWordList(text) {
  if (/[,;•·]|\r?\n/.test(text)) return false;
  const w = wordsOf(text);
  if (w.length < 5) return false;
  const stops = w.map(normalise).filter((x) => STOP_WORDS.has(x)).length;
  return stops / w.length <= 0.2;
}
function wordSplit(text) {
  const chunks = [];
  let cur = [];
  for (const word of wordsOf(text)) {
    const isStop = STOP_WORDS.has(normalise(word));
    const prevWasStop = cur.length ? STOP_WORDS.has(normalise(cur[cur.length - 1])) : false;
    if (cur.length === 0 || isStop || prevWasStop) cur.push(word);
    else {
      chunks.push(cur.join(" "));
      cur = [word];
    }
  }
  if (cur.length) chunks.push(cur.join(" "));
  return chunks;
}
// Brain-dump text often carries conversational scaffolding that shouldn't
// end up as the item's actual title — "I need to hoover the stairs" should
// become "Hoover the stairs", not keep the "I need to" attached.
const LEADING_FILLER = /^(?:i(?:'ve| have| had)?\s+(?:need|got|gotta|have|want|must|should)\s+to\s+|i\s+must\s+|i\s+should\s+|remember\s+to\s+|don'?t\s+forget\s+to\s+|need\s+to\s+|have\s+to\s+|gotta\s+|got\s+to\s+)/i;
function stripFiller(text) {
  return text.replace(LEADING_FILLER, "").trim();
}

function localSplit(text) {
  const raw = looksLikeWordList(text)
    ? wordSplit(text)
    : String(text || "")
        .split(/\r?\n|[;•·]|,(?![^()]*\))| and (?=[a-z])| then | also /i)
        .map((t) => t.replace(/^[\s\-–—*+.\d)]+/, "").trim())
        .filter((t) => t.length > 1);
  const seen = new Set();
  return raw
    .filter((t) => {
      const k = t.toLowerCase();
      if (seen.has(k)) return false;
      seen.add(k);
      return true;
    })
    .slice(0, 30)
    .map((raw) => {
      const t = stripFiller(raw) || raw;
      return { tempId: uid(), title: t.charAt(0).toUpperCase() + t.slice(1, 140), type: inferType(t), selected: true };
    });
}
function looksSplittable(text) {
  const t = String(text || "").trim();
  if (t.length < 12) return false;
  if (/\r?\n/.test(t)) return true;
  const sep = (t.match(/[,;•·]/g) || []).length;
  if (sep >= 2) return true;
  if (sep === 1 && t.length > 28) return true;
  const join = (t.match(/\b(and|then|also|plus)\b/gi) || []).length;
  if (join >= 2) return true;
  if (join >= 1 && sep >= 1) return true;
  if (join >= 1 && t.length > 45) return true;
  if (looksLikeWordList(t)) return true;
  return localSplit(t).length >= 3;
}

/* ---------------------------------------------------------------------- */
/* AI extraction — real sorting, not regex. Only called when looksSplittable */
/* flags text as a list; a single simple capture never makes a network call. */
/* Falls back to localSplit on any failure (offline, rate limit, bad reply). */
/* ---------------------------------------------------------------------- */

const SPLIT_PROMPT = `You are looking at a chunk of typed or dictated text — someone speaking or typing out a stream-of-consciousness brain dump, often with run-on sentences, "and also", "oh and", filler words, or no punctuation at all (common with voice dictation).

Default to splitting aggressively. Any comma-separated, "and"-separated, or newline-separated list of short items is almost always meant as SEPARATE items, even when they're thematically related (a shopping list, several chores, a few ideas in a row) — each one should become its own item so it can be individually checked off later. For example, "cake, lemon, potato" is three separate items typed "buy" — titled simply "Cake", "Lemon", "Potato" — NOT one combined item, and never merge a plain list into a single item just because the entries are short or share a category.

Keep titles as close to the person's own words as possible. Do NOT prepend a verb that just restates the type — the type is already shown next to the item, so "Buy cake" is redundant where "Cake" is correct. Same for other types: a research item they wrote as "children's book subscriptions" stays that, not "Research children's book subscriptions". Only keep a verb if they actually said it ("ring plumber" stays "Ring plumber") or if the title would be meaningless without it.

Only keep two things together as ONE item when one part is clearly a detail, reason, or sub-point ABOUT the other — not merely related to it. For example "garden office door, needs a stop because it swings in the wind" is one item (title: "Garden office door", notes: "Needs a stop — swings in the wind"), because the second clause is explaining the first, not naming something new.

When genuinely unsure whether two things are separate or one, prefer splitting them — a spurious split is easy to undo (the user can just delete or merge in review), but a wrongful merge hides an item inside another one where it's easy to miss.

Dictated text often has NO punctuation at all. "papers eggs lemons sausages walk the dog" is five separate items (papers / eggs / lemons / sausages / walk the dog) — a run of unrelated nouns with no linking words is a list, even without a single comma. Use the words themselves to find the boundaries, and keep short verb phrases like "walk the dog" or "ring the vet" intact.

Where punctuation IS present, split on SEPARATORS, not on words. Commas, "and", newlines, bullets, and semicolons are separators. A phrase with no separator in it is ONE thought, however many nouns it contains — "Minecraft potions idea" is a single idea (title: "Minecraft potions"), NOT "Minecraft" plus "Potions idea". Never break a single phrase into fragments that lose their meaning apart.

Not every comma is a list separator — rambling speech uses commas for pauses and asides too ("so I was thinking, maybe, about doing the project this weekend, if I have time"). That's ONE thought with a hesitant delivery, not four items — a comma only marks a boundary between separate items when what's on each side could stand alone as its own thing. If splitting would produce a fragment that's meaningless on its own (like "maybe" or "if I have time" as standalone items), that's a sign it was never a list — return it as a single item instead, cleaned up into a proper sentence.

Clean up dictation artifacts (stray "um", repeated words, missing punctuation) when forming each title, but don't invent information that wasn't said.

Types: "task" (something to do), "buy" (something to get), "project" (a bigger multi-step undertaking, usually with a name), "note" (anything else worth keeping — an idea, a question to look into, a thought, or information with no action attached).

Respond with ONLY a raw JSON array, no markdown code fences, no explanation before or after. Each element must look like:
{"title": "short title, 3-8 words", "type": "task|buy|note|project", "notes": "related detail, or empty string"}`;


// No backend proxy exists yet for this deployment (direct browser calls to
// api.anthropic.com don't work outside the artifact sandbox — see the iOS
// handover doc). Flip this to false once a proxy is wired up; until then,
// skip the doomed network attempt and go straight to the same graceful
// local-parsing fallback a genuine network failure would produce.
const NO_BACKEND_PROXY = true;

async function extractItemsFromText(rawText) {
  if (NO_BACKEND_PROXY) {
    throw new Error("No backend proxy configured for AI extraction yet — using local parsing.");
  }
  const body = {
    model: "claude-sonnet-4-6",
    max_tokens: 1500,
    messages: [
      {
        role: "user",
        content: [{ type: "text", text: `${SPLIT_PROMPT}\n\nHere's the text:\n"""\n${rawText}\n"""` }],
      },
    ],
  };
  return parseExtractionResponse(body);
}

// The model is instructed to reply with only a JSON array, but real-world
// replies sometimes wrap it in prose, use a single object instead of an
// array, or (rarely) get cut off. Try progressively looser strategies
// before giving up, so a slightly-off reply still produces usable items
// instead of a dead end.

function salvageJsonArray(rawText) {
  const cleaned = rawText.replace(/```json|```/g, "").trim();

  const bracketStart = cleaned.indexOf("[");
  const bracketEnd = cleaned.lastIndexOf("]");
  if (bracketStart !== -1 && bracketEnd > bracketStart) {
    try {
      const parsed = JSON.parse(cleaned.slice(bracketStart, bracketEnd + 1));
      if (Array.isArray(parsed) && parsed.length) return parsed;
    } catch (e) {
      /* fall through */
    }
  }

  try {
    const parsed = JSON.parse(cleaned);
    if (Array.isArray(parsed) && parsed.length) return parsed;
    if (parsed && Array.isArray(parsed.items) && parsed.items.length) return parsed.items;
  } catch (e) {
    /* fall through */
  }

  // Last resort: pull out individual {...} objects one at a time, even if
  // the surrounding array syntax is malformed or truncated.
  const objectMatches = cleaned.match(/\{[^{}]*\}/g);
  if (objectMatches && objectMatches.length) {
    const salvaged = [];
    for (const m of objectMatches) {
      try {
        salvaged.push(JSON.parse(m));
      } catch (e) {
        /* skip this fragment */
      }
    }
    if (salvaged.length) return salvaged;
  }

  return null;
}

// The response envelope sometimes arrives truncated or corrupted in this
// environment (e.g. missing its opening bytes) even on a status 200 with a
// perfectly good model reply inside. So rather than depending on the envelope
// parsing cleanly, pull the assistant's text out of whatever we actually got.


// Dictation and quick typing often arrive with no punctuation at all
// ("papers eggs lemons sausages walk the dog"), so separators alone aren't
// enough to spot a list. These function words are the giveaway: a real
// sentence is full of them, a rattled-off list has almost none.

function extractModelText(rawBody) {
  // Happy path: the envelope is intact. Join every text block (there can be
  // more than one) and ignore empty ones, so an empty leading block doesn't
  // make us give up on a reply that's actually there.
  try {
    const data = JSON.parse(rawBody);
    const joined = (data.content || [])
      .filter((b) => b && b.type === "text" && typeof b.text === "string")
      .map((b) => b.text)
      .join("\n")
      .trim();
    if (joined) return joined;
  } catch (e) {
    /* fall through to salvage */
  }

  // Salvage path: find the "text":"..." field(s) directly in the raw bytes and
  // unescape them, so a damaged envelope still yields the model's reply.
  const matches = rawBody.match(/"text"\s*:\s*"((?:[^"\\]|\\.)*)"/g);
  if (matches && matches.length) {
    const pieces = [];
    for (const m of matches) {
      const inner = m.replace(/^"text"\s*:\s*/, "");
      try {
        const v = JSON.parse(inner);
        if (v && String(v).trim()) pieces.push(v);
      } catch (e) {
        /* skip unparseable fragment */
      }
    }
    if (pieces.length) return pieces.join("\n");
  }

  // Last resort: hand back the raw body and let salvageJsonArray try on it.
  return rawBody;
}

// Reading the response body has proven flaky in this environment: the same
// request can return good content, a body truncated at the front, or nothing
// at all. So read it at the byte level (more reliable than res.text() here)
// and retry a few times before giving up, since the failures are intermittent
// rather than deterministic.
async function readBodyText(res) {
  try {
    const buf = await res.arrayBuffer();
    if (buf && buf.byteLength) {
      return new TextDecoder("utf-8").decode(buf);
    }
  } catch (e) {
    /* fall through */
  }
  return "";
}

async function parseExtractionResponse(body, attempts = 3) {
  const problems = [];

  for (let attempt = 1; attempt <= attempts; attempt++) {
    // A hanging connection (technically "connected", actually dead — the
    // common case for bad wifi, not the same as navigator.onLine=false)
    // has no natural failure to catch without this. Without a bound, a
    // stalled request could block the fallback indefinitely instead of
    // failing fast into local processing.
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 8000);
    try {
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify(body),
        signal: controller.signal,
      });
      clearTimeout(timeoutId);
      const rawBody = await readBodyText(res);

      if (!res.ok) {
        problems.push(`attempt ${attempt}: HTTP ${res.status} — ${rawBody.slice(0, 400) || "(empty body)"}`);
        // Auth/permission failures won't fix themselves on a retry.
        if (res.status === 401 || res.status === 403) break;
      } else {
        const raw = extractModelText(rawBody);
        const parsed = salvageJsonArray(raw);
        if (parsed) {
          return parsed.map((p) => ({
            tempId: uid(),
            title: String((p && p.title) || "Untitled thought").slice(0, 140),
            type: p && TYPE_ORDER.includes(p.type) ? p.type : "task",
            notes: String((p && p.notes) || ""),
            selected: true,
          }));
        }
        problems.push(
          `attempt ${attempt}: HTTP 200, body ${rawBody.length} chars, usable text ${
            raw && raw.trim() ? `"${raw.slice(0, 120)}"` : "(none)"
          }`
        );
      }
    } catch (e) {
      clearTimeout(timeoutId);
      const isTimeout = e.name === "AbortError";
      problems.push(`attempt ${attempt}: ${isTimeout ? "timed out after 8s" : e.message || String(e)}`);
    }

    if (attempt < attempts) await new Promise((r) => setTimeout(r, 500 * attempt));
  }

  console.error("Bonce: all extraction attempts failed", problems);
  throw new Error(`Couldn't get a usable reply after ${problems.length} tr${problems.length === 1 ? "y" : "ies"}:\n${problems.join("\n")}`);
}

/* ---------------------------------------------------------------------- */
/* Wording — every card reads as an instruction, whatever its type          */
/* ---------------------------------------------------------------------- */

const IMPERATIVE_VERBS = new Set([
  "wipe", "change", "hoover", "vacuum", "empty", "ring", "call", "email", "buy", "get",
  "fetch", "sort", "fix", "repair", "clean", "tidy", "check", "book", "pay", "write",
  "update", "renew", "cancel", "submit", "finish", "review", "send", "pick", "water",
  "feed", "walk", "take", "make", "clear", "return", "collect", "plan", "install",
  "replace", "order", "print", "sign", "pack", "post", "do", "ask", "tell", "find",
  "read", "cook", "plant", "mow", "paint", "wash", "iron", "sweep", "text", "chase",
  "start", "draft", "back", "photograph", "scan", "upload",
]);
const DETERMINERS = new Set([
  "the", "a", "an", "your", "my", "his", "her", "its", "our", "their",
  "this", "that", "these", "those", "some", "any",
]);
// Words that attach to a verb as one phrasal unit ("clear up", "sort
// out", "tidy away") rather than starting the object noun phrase.
const PARTICLES = new Set(["up", "out", "away", "down", "off", "through", "back", "over", "aside"]);
// Prepositions that start their own complete phrase ("under the sofa"),
// as distinct from particles that attach to the verb itself.
const PREPOSITIONS = new Set(["under", "over", "behind", "beside", "near", "inside", "outside", "above", "below", "between", "around", "before", "after"]);

function toInstruction(title, type) {
  const words = title.trim().split(/\s+/);
  if (!words.length) return title;
  const first = (words[0] || "").toLowerCase().replace(/[^a-z]/g, "");
  const lower = `${title.charAt(0).toLowerCase()}${title.slice(1)}`;

  if (type === "buy") {
    if (first === "buy" || first === "get" || first === "order") return title;
    return `Buy ${lower}`;
  }
  // Projects just show their name — "Crack on with X" was awkward for
  // almost anything that wasn't a single obvious noun.
  if (type === "project") return title;
  // Notes just show their name too, like projects — "Think about X" added
  // words without adding meaning, and read strangely on anything that
  // already implied thought ("research screwdrivers" didn't need it).
  if (type === "note") return title;
  if (!IMPERATIVE_VERBS.has(first)) {
    // "Do the X" reads fine for a single bare noun ("Laundry") but gets
    // clunky fast on anything longer ("Do the work emails") — so it's only
    // applied to single-word titles. Multi-word non-verb titles just show
    // as typed instead of forcing them into a sentence that doesn't fit.
    return words.length === 1 ? `Do the ${lower}` : title;
  }

  const rest = words.slice(1);
  if (!rest.length) return title;
  const restClean = rest.map((w) => w.toLowerCase().replace(/[^a-z]/g, ""));
  const second = rest[0];
  const secondClean = restClean[0];
  const looksLikeName = /^[A-Z]/.test(second) && second !== second.toUpperCase();
  // Checked across the WHOLE remainder, not just the next word — "Hoover
  // under the sofa" has its "the" three words in, not immediately after
  // the verb, but inserting another one anyway gave "Hoover the under the
  // sofa". A phrase that already has an article anywhere doesn't need one
  // added, wherever it happens to sit.
  const alreadyHasDeterminer = restClean.some((w) => DETERMINERS.has(w));
  if (alreadyHasDeterminer || looksLikeName) return title;
  if (PARTICLES.has(secondClean) || PREPOSITIONS.has(secondClean)) {
    // Phrasal verb ("clear up") or a preposition starting its own phrase
    // ("hoover under X") — either way "the" belongs after that word, not
    // right after the verb. Inserting blindly there gave "Clear the up
    // dog mess" / "Hoover the under sofa".
    return rest.length <= 1 ? title : `${words[0]} ${second} the ${rest.slice(1).join(" ")}`;
  }
  return `${words[0]} the ${rest.join(" ")}`;
}

// What actually renders on a card: the person's own wording if they've set
// one, otherwise the auto-generated instruction.
function displayText(item) {
  return item.displayOverride && item.displayOverride.trim() ? item.displayOverride : toInstruction(item.title, item.type);
}

